CREATE OR REPLACE FUNCTION public.network_workspace_access(_ws uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND w.status='active' AND p.status='active' AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_manage_trips OR (NOT _manage AND m.can_view_workspace_requests))) $$;
CREATE OR REPLACE FUNCTION public.network_list_activity() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]'::jsonb) FROM (SELECT d.id,d.mfn_id,d.source_mfn_id,d.service_type,d.pickup_area,d.destination_area,d.pickup_date,d.pickup_time,d.trip_type,d.estimated_miles,d.capability,d.amount_cents,d.expires_at,d.current_radius,d.created_at,CASE WHEN d.selected_workspace_id IS NULL AND d.status NOT IN ('closed','canceled','unavailable') AND d.created_at<=now()-interval '24 hours' THEN 'needs_attention' ELSE d.status END status,(SELECT display_name FROM public.workspaces WHERE id=d.source_workspace_id) source_business,public.network_source_access(d.id,true) can_manage,(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.created_at),'[]'::jsonb) FROM public.provider_trip_offers o WHERE o.distribution_id=d.id) offers,(SELECT coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.sent_at),'[]'::jsonb) FROM public.trip_distribution_waves w WHERE w.distribution_id=d.id) waves,(SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.created_at),'[]'::jsonb) FROM public.trip_offer_negotiations n JOIN public.provider_trip_offers o ON o.id=n.offer_id WHERE o.distribution_id=d.id) negotiations,(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at),'[]'::jsonb) FROM public.trip_network_events e WHERE e.distribution_id=d.id) events FROM public.trip_distributions d WHERE public.network_source_access(d.id,false)) x $$;
CREATE OR REPLACE FUNCTION public.network_mark_attention() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; n integer:=0; BEGIN IF NOT public.admin_can('requests','manage') THEN RAISE EXCEPTION 'Operations permission required'; END IF; FOR d IN SELECT * FROM public.trip_distributions WHERE public.admin_can_account(source_workspace_id) AND selected_workspace_id IS NULL AND status NOT IN ('needs_attention','closed','canceled','unavailable') AND created_at<=now()-interval '24 hours' FOR UPDATE LOOP UPDATE public.trip_distributions SET status='needs_attention',updated_at=now() WHERE id=d.id; PERFORM public.network_audit(d.id,NULL,'needs_attention','{}'); PERFORM public.network_notify(d.source_workspace_id,'Distribution needs attention',NULL,true); n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.network_mark_attention() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_mark_attention() TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_network_trip_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF (NEW.network_provider_workspace_id IS NOT NULL OR NEW.network_distribution_id IS NOT NULL OR NEW.network_status IS NOT NULL) AND current_user NOT IN ('postgres','service_role') THEN RAISE EXCEPTION 'Controlled network assignment required'; END IF; ELSE IF (NEW.network_provider_workspace_id IS DISTINCT FROM OLD.network_provider_workspace_id OR NEW.network_distribution_id IS DISTINCT FROM OLD.network_distribution_id OR NEW.network_status IS DISTINCT FROM OLD.network_status) AND (coalesce(current_setting('app.network_write',true),'')<>'true' OR current_user NOT IN ('postgres','service_role')) THEN RAISE EXCEPTION 'Controlled network assignment required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_network_trip_insert BEFORE INSERT ON public.trips FOR EACH ROW EXECUTE FUNCTION public.guard_network_trip_fields();
CREATE OR REPLACE FUNCTION public.network_assigned_access(_ws uuid,_driver uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.network_workspace_access(_ws,true) OR EXISTS(SELECT 1 FROM public.drivers d JOIN public.workspace_members m ON m.workspace_id=d.workspace_id AND m.user_id=d.user_id JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE d.id=_driver AND d.user_id=auth.uid() AND d.workspace_id=_ws AND p.status='active' AND w.status='active') $$;
REVOKE ALL ON FUNCTION public.network_assigned_access(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_assigned_access(uuid,uuid) TO authenticated,service_role;
CREATE POLICY network_exact_details_boundary ON public.trips AS RESTRICTIVE FOR SELECT TO authenticated USING(network_provider_workspace_id IS NULL OR public.network_assigned_access(network_provider_workspace_id,driver_id) OR public.network_source_access(network_distribution_id,false));
CREATE OR REPLACE FUNCTION public.network_sync_request_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.request_id IS NOT NULL THEN UPDATE public.ride_requests SET network_status=CASE NEW.status WHEN 'ready' THEN 'ready_for_distribution' WHEN 'provider_selected' THEN 'reserved' ELSE NEW.status END WHERE id=NEW.request_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER network_sync_request_status AFTER INSERT OR UPDATE OF status ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.network_sync_request_status();
CREATE OR REPLACE FUNCTION public.trips_sync_reservation_state() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.reservation_state:=public.compute_trip_reservation_state(NEW.status,NEW.payment_status,NEW.assigned_to,NEW.completed_at,NEW.cancel_reason,NEW.no_show_reason,public.reservation_scheduled_at(NEW.pickup_date,NEW.pickup_time,CASE WHEN NEW.round_trip THEN NEW.return_date ELSE NULL END,NEW.return_pickup_time)); IF NEW.network_provider_workspace_id IS NOT NULL AND NEW.network_status='reserved' AND NEW.status NOT IN ('completed','canceled','cancelled','no_show') THEN NEW.reservation_state:=CASE WHEN NEW.pickup_date<current_date THEN 'past' ELSE 'unconfirmed' END; END IF; RETURN NEW; END $$;
DO $$ DECLARE name text; def text; BEGIN FOREACH name IN ARRAY ARRAY['trips_auto_assign_provider','notify_dispatch_on_new_trip','notify_auto_referral_target','fin_snapshot_on_create'] LOOP SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=name LIMIT 1; def:=regexp_replace(def,'BEGIN','BEGIN IF coalesce(current_setting(''app.network_write'',true),'''')=''true'' THEN RETURN NEW; END IF;'); EXECUTE def; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.network_accept_offer(_offer uuid,_approve boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.provider_trip_offers; d public.trip_distributions; tid uuid; comp record; previous_flag text; acceptor uuid; BEGIN SELECT distribution_id INTO tid FROM public.provider_trip_offers WHERE id=_offer; SELECT * INTO d FROM public.trip_distributions WHERE id=tid FOR UPDATE; SELECT * INTO o FROM public.provider_trip_offers WHERE id=_offer FOR UPDATE; IF o.id IS NULL OR d.id IS NULL OR d.selected_workspace_id IS NOT NULL OR d.status NOT IN ('ready','offers_sent','negotiating','needs_attention') OR d.expires_at<=now() OR o.expires_at<=now() OR o.status NOT IN ('pending','revised','countered') THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; IF _approve THEN IF NOT public.network_source_access(d.id,true) OR o.status<>'countered' THEN RAISE EXCEPTION 'Counteroffer approval permission required'; END IF; SELECT actor_id INTO acceptor FROM public.trip_offer_negotiations WHERE offer_id=o.id AND side='provider' AND action='counter' ORDER BY created_at DESC LIMIT 1; ELSE IF NOT public.network_workspace_access(o.provider_workspace_id,true) OR o.status='countered' THEN RAISE EXCEPTION 'Offer acceptance permission required'; END IF; acceptor:=auth.uid(); END IF; IF NOT EXISTS(SELECT 1 FROM public.workspaces w JOIN public.provider_network_profiles np ON np.workspace_id=w.id WHERE w.id=o.provider_workspace_id AND w.account_type='provider' AND w.status='active' AND w.provider_verified AND NOT w.is_test_account AND np.visible AND np.accepting_connections AND np.service_base_verified_at IS NOT NULL AND np.service_base_lat BETWEEN -90 AND 90 AND np.service_base_lng BETWEEN -180 AND 180 AND d.capability=ANY(np.approved_service_types) AND (np.eligibility_expires_at IS NULL OR np.eligibility_expires_at>now()) AND public.haversine_miles(d.pickup_lat,d.pickup_lng,np.service_base_lat,np.service_base_lng)<=(SELECT radius_miles FROM public.trip_distribution_waves WHERE id=o.wave_id)) THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; previous_flag:=coalesce(current_setting('app.network_write',true),''); PERFORM set_config('app.network_write','true',true); tid:=d.trip_id; IF d.request_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.ride_requests WHERE id=d.request_id AND NOT is_test AND trip_kind='passenger' AND transport_type<>'delivery' AND status NOT IN ('canceled','cancelled','completed','declined','unavailable')) THEN RAISE EXCEPTION 'Source request unavailable'; END IF; SELECT coalesce(tid,promoted_trip_id) INTO tid FROM public.ride_requests WHERE id=d.request_id FOR UPDATE; END IF; IF tid IS NULL THEN tid:=public.promote_ride_request_to_trip(d.request_id); END IF; IF tid IS NULL THEN RAISE EXCEPTION 'Source trip unavailable'; END IF; UPDATE public.trips SET network_provider_workspace_id=o.provider_workspace_id,network_distribution_id=d.id,network_status='reserved',reservation_state=CASE WHEN pickup_date<current_date THEN 'past' ELSE 'unconfirmed' END WHERE id=tid AND network_provider_workspace_id IS NULL AND status NOT IN ('canceled','cancelled','completed','no_show'); IF NOT FOUND THEN PERFORM set_config('app.network_write',previous_flag,true); RETURN jsonb_build_object('ok',false,'error','This offer is no longer available'); END IF; UPDATE public.trip_distributions SET selected_workspace_id=o.provider_workspace_id,selected_offer_id=o.id,accepted_by=acceptor,approved_by=auth.uid(),status='provider_selected',trip_id=tid,updated_at=now() WHERE id=d.id; UPDATE public.provider_trip_offers SET status='accepted',accepted_by=acceptor,approved_by=auth.uid(),updated_at=now() WHERE id=o.id; FOR comp IN SELECT id,provider_workspace_id FROM public.provider_trip_offers WHERE distribution_id=d.id AND id<>o.id AND status IN ('pending','countered','revised') LOOP UPDATE public.provider_trip_offers SET status='closed',updated_at=now() WHERE id=comp.id; PERFORM public.network_notify(comp.provider_workspace_id,'Offer no longer available',comp.id,false); END LOOP; INSERT INTO public.trip_offer_negotiations(offer_id,actor_id,actor_mfn_id,side,action,amount_cents) VALUES(o.id,auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),CASE WHEN _approve THEN 'source' ELSE 'provider' END,'accept',o.amount_cents); PERFORM public.network_audit(d.id,o.id,'provider_selected',jsonb_build_object('provider_workspace_id',o.provider_workspace_id,'trip_id',tid,'amount_cents',o.amount_cents)); PERFORM public.network_notify(o.provider_workspace_id,CASE WHEN _approve THEN 'Counteroffer accepted' ELSE 'Provider selected' END,o.id,false); IF d.source_workspace_id IS NOT NULL THEN PERFORM public.network_notify(d.source_workspace_id,'Provider selected',o.id,false); END IF; PERFORM set_config('app.network_write',previous_flag,true); RETURN jsonb_build_object('ok',true,'trip_id',tid); END $$;
CREATE OR REPLACE FUNCTION public.network_assign_driver_slot(_trip uuid,_driver uuid,_time time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips; ws uuid; dr public.drivers; BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Trip unavailable'; END IF; ws:=t.network_provider_workspace_id; IF ws IS NULL THEN IF t.assigned_to IS DISTINCT FROM auth.uid() AND t.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Trip management permission required'; END IF; SELECT CASE WHEN count(*)=1 THEN min(workspace_id::text)::uuid END INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=auth.uid() AND w.status='active'; END IF; IF ws IS NULL OR NOT public.network_workspace_access(ws,true) THEN RAISE EXCEPTION 'Trip management permission required'; END IF; IF _driver IS NOT NULL THEN SELECT * INTO dr FROM public.drivers WHERE id=_driver AND workspace_id=ws AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Active driver in this business required'; END IF; END IF; UPDATE public.trips SET driver_id=_driver,scheduled_start_time=_time WHERE id=t.id; END $$;
REVOKE ALL ON FUNCTION public.network_assign_driver_slot(uuid,uuid,time) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_assign_driver_slot(uuid,uuid,time) TO authenticated;